head.b:skin:
:root {
  --bg: #07090e;
  --bg-secondary: #0d111a;
  --card: #131824;
  --card-hover: #1a2233;
  --border: #1f2738;
  --border-focus: #e50914;
  --text: #f1f5f9;
  --text-muted: #94a3b8;
  --primary: #e50914;
  --primary-light: #ff2a38;
  --primary-glow: rgba(229, 9, 20, 0.35);
  --green: #10b981;
  --green-glow: rgba(16, 185, 129, 0.25);
  --gold: #f59e0b;
  --blue: #3b82f6;
  --purple: #8b5cf6;
  --radius: 14px;
  --font: 'Plus Jakarta Sans', 'Hind Siliguri', sans-serif;
  --header-height: 60px;
  --nav-height: 62px;
}

[data-theme='light'] {
  --bg: #f8fafc;
  --bg-secondary: #f1f5f9;
  --card: #ffffff;
  --card-hover: #f8fafc;
  --border: #e2e8f0;
  --border-focus: #e50914;
  --text: #0f172a;
  --text-muted: #64748b;
  --primary-glow: rgba(229, 9, 20, 0.15);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html {
  scroll-behavior: smooth;
  background: var(--bg);
}

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  font-size: 14px;
  line-height: 1.5;
  padding-bottom: 75px;
  overflow-x: hidden;
  transition: background 0.3s, color 0.3s;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; object-fit: cover; }
button { cursor: pointer; border: none; background: none; color: inherit; font-family: inherit; }
input, select { font-family: inherit; }

/* Custom Scrollbar */
::-webkit-scrollbar { width: 5px; height: 5px; }
::-webkit-scrollbar-track { background: var(--bg); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 999px; }
::-webkit-scrollbar-thumb:hover { background: var(--primary); }

.container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 16px;
  width: 100%;
}

/* ===== TOPBAR ===== */
.topbar {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--header-height);
  background: rgba(7, 9, 14, 0.9);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
  transition: background 0.3s;
}

[data-theme='light'] .topbar {
  background: rgba(255, 255, 255, 0.92);
}

.topbar-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.menu-btn {
  width: 38px;
  height: 38px;
  border-radius: 11px;
  background: var(--card);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  color: var(--text);
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}
.menu-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
  transform: translateY(-1px);
}

.brand-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 19px;
  font-weight: 800;
  letter-spacing: -0.5px;
}
.brand-icon-box {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: linear-gradient(135deg, var(--primary), var(--primary-light));
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 16px;
  box-shadow: 0 4px 12px var(--primary-glow);
}
.brand-logo .live-tag {
  background: linear-gradient(135deg, var(--primary), var(--primary-light));
  color: #fff;
  font-size: 9px;
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 6px;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  animation: pulse-glow 2s infinite;
}
@keyframes pulse-glow {
  0%, 100% { box-shadow: 0 0 0 rgba(229, 9, 20, 0); }
  50% { box-shadow: 0 0 12px var(--primary-glow); }
}

.topbar-center {
  flex: 1;
  max-width: 440px;
  margin: 0 16px;
}

.search-bar {
  display: flex;
  align-items: center;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 0 12px;
  height: 38px;
  transition: all 0.2s;
}
.search-bar:focus-within {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px var(--primary-glow);
}
.search-bar i {
  color: var(--text-muted);
  font-size: 13px;
  margin-right: 8px;
}
.search-bar input {
  background: transparent;
  border: none;
  outline: none;
  color: var(--text);
  font-size: 13px;
  width: 100%;
}
.search-bar input::placeholder {
  color: var(--text-muted);
}

.topbar-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.online-chip {
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--card);
  border: 1px solid var(--border);
  padding: 5px 11px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
}
.pulse-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 8px var(--green);
  animation: pulse 1.6s infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.35; transform: scale(1.2); }
}

.icon-button {
  width: 38px;
  height: 38px;
  border-radius: 11px;
  background: var(--card);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  color: var(--text);
  transition: all 0.2s;
}
.icon-button:hover {
  border-color: var(--primary);
  color: var(--primary);
}

/* ===== TICKER ===== */
.news-ticker {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  height: 36px;
  display: flex;
  align-items: center;
  overflow: hidden;
  font-size: 12px;
}
.ticker-label {
  background: var(--primary);
  color: #fff;
  font-size: 10px;
  font-weight: 800;
  padding: 0 10px;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 5px;
  text-transform: uppercase;
  flex-shrink: 0;
  z-index: 2;
}
.ticker-marquee {
  white-space: nowrap;
  display: inline-block;
  animation: ticker-anim 28s linear infinite;
  color: var(--text-muted);
  padding-left: 20px;
}
.ticker-marquee:hover {
  animation-play-state: paused;
}
.ticker-marquee span {
  margin: 0 14px;
}
.ticker-marquee strong {
  color: var(--text);
}
@keyframes ticker-anim {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ===== SIDEBAR DRAWER ===== */
.drawer-overlay {
  position: fixed;
  inset: 0;
  z-index: 199;
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(6px);
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
.drawer-overlay.active {
  opacity: 1;
  visibility: visible;
}

.drawer {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: 300px;
  max-width: 86vw;
  background: var(--bg-secondary);
  border-right: 1px solid var(--border);
  z-index: 200;
  transform: translateX(-100%);
  transition: transform 0.32s cubic-bezier(0.16, 1, 0.3, 1);
  display: flex;
  flex-direction: column;
  overflow-y: auto;
}
.drawer.active {
  transform: translateX(0);
}

.drawer-header {
  padding: 18px 20px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.drawer-close {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: var(--card);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

.drawer-nav {
  padding: 14px 12px;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.drawer-section-label {
  font-size: 10px;
  font-weight: 800;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 10px 14px 4px;
}
.drawer-nav-link {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 14px;
  border-radius: 10px;
  color: var(--text-muted);
  font-weight: 600;
  font-size: 13px;
  transition: all 0.2s;
}
.drawer-nav-link i {
  font-size: 15px;
  width: 20px;
  text-align: center;
}
.drawer-nav-link:hover, .drawer-nav-link.active {
  background: var(--card);
  color: var(--text);
}
.drawer-nav-link.active {
  color: var(--primary);
  font-weight: 700;
  border-left: 3px solid var(--primary);
}

.drawer-footer {
  padding: 16px;
  border-top: 1px solid var(--border);
  background: var(--card);
}
.drawer-footer .dev-tag {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 6px;
}
.drawer-footer .dev-tag strong {
  color: var(--gold);
}

/* ===== HERO SLIDER ===== */
.hero-slider-wrap {
  position: relative;
  margin: 16px 0 20px;
  border-radius: 18px;
  overflow: hidden;
  background: var(--card);
  border: 1px solid var(--border);
  min-height: 230px;
  box-shadow: 0 12px 36px rgba(0,0,0,0.4);
}

.hero-slide {
  display: none;
  position: relative;
  min-height: 230px;
  background-size: cover;
  background-position: center;
  padding: 24px;
  align-items: flex-end;
}
.hero-slide.active {
  display: flex;
}
.hero-slide::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(7,9,14,0.15) 0%, rgba(7,9,14,0.94) 85%);
  z-index: 1;
}

.hero-slide-content {
  position: relative;
  z-index: 2;
  max-width: 620px;
}
.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  background: var(--primary);
  color: #fff;
  margin-bottom: 8px;
  letter-spacing: 0.5px;
}
.hero-slide-content h2 {
  font-size: 22px;
  font-weight: 800;
  line-height: 1.25;
  margin-bottom: 6px;
  text-shadow: 0 2px 8px rgba(0,0,0,0.8);
}
.hero-slide-content p {
  font-size: 13px;
  color: var(--text-muted);
  margin-bottom: 12px;
  line-height: 1.4;
}
.hero-watch-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: linear-gradient(135deg, var(--primary), var(--primary-light));
  color: #fff;
  padding: 9px 20px;
  border-radius: 11px;
  font-weight: 700;
  font-size: 13px;
  box-shadow: 0 4px 18px var(--primary-glow);
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
}
.hero-watch-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 24px rgba(229, 9, 20, 0.5);
}

.hero-dots {
  position: absolute;
  bottom: 14px;
  right: 18px;
  z-index: 3;
  display: flex;
  gap: 6px;
}
.hero-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.3);
  cursor: pointer;
  transition: all 0.2s;
}
.hero-dot.active {
  width: 22px;
  border-radius: 8px;
  background: var(--primary);
}

/* ===== FILTER TABS ===== */
.filter-tabs {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 6px;
  margin-bottom: 20px;
}
.filter-tabs::-webkit-scrollbar { display: none; }
.tab-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 15px;
  border-radius: 11px;
  background: var(--card);
  border: 1px solid var(--border);
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  transition: all 0.2s;
}
.tab-btn:hover {
  color: var(--text);
  border-color: var(--border-focus);
}
.tab-btn.active {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
  box-shadow: 0 4px 14px var(--primary-glow);
}

/* ===== SUB CATEGORY PILLS ===== */
.sub-filter-row {
  display: flex;
  align-items: center;
  gap: 6px;
  overflow-x: auto;
  padding-bottom: 8px;
  margin-bottom: 14px;
}
.sub-filter-row::-webkit-scrollbar { display: none; }
.sub-chip {
  padding: 5px 12px;
  border-radius: 8px;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
  transition: all 0.2s;
  cursor: pointer;
}
.sub-chip:hover, .sub-chip.active {
  color: var(--text);
  border-color: var(--primary);
  background: var(--card);
}
.sub-chip.active {
  color: var(--primary);
  font-weight: 700;
}

/* ===== SECTION HEADER ===== */
.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 14px;
}
.section-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 16px;
  font-weight: 800;
}
.section-title i {
  color: var(--primary);
  font-size: 17px;
}
.see-all-btn {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  display: flex;
  align-items: center;
  gap: 4px;
  transition: color 0.2s;
}
.see-all-btn:hover {
  color: var(--primary);
}

/* ===== MATCH CARDS ===== */
.matches-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(290px, 1fr));
  gap: 14px;
  margin-bottom: 26px;
}

.match-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px 16px;
  position: relative;
  cursor: pointer;
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  overflow: hidden;
}
.match-card:hover {
  transform: translateY(-2px);
  border-color: rgba(229, 9, 20, 0.5);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.35);
}

.match-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 10px;
  font-size: 11px;
}
.match-tournament {
  color: var(--text-muted);
  font-weight: 600;
  max-width: 65%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.match-status-badge {
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}
.match-status-badge.live {
  background: rgba(239, 68, 68, 0.2);
  color: #f87171;
  border: 1px solid rgba(239, 68, 68, 0.4);
  animation: live-blink 1.5s infinite;
}
@keyframes live-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}
.match-status-badge.upcoming {
  background: rgba(59, 130, 246, 0.18);
  color: #93c5fd;
  border: 1px solid rgba(59, 130, 246, 0.3);
}

.match-teams-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 0;
}
.team-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1;
  min-width: 0;
  text-align: center;
}
.team-logo {
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: var(--bg-secondary);
  border: 1.5px solid var(--border);
  padding: 3px;
  margin-bottom: 6px;
  object-fit: cover;
  transition: transform 0.2s;
}
.match-card:hover .team-logo {
  transform: scale(1.08);
}
.team-name {
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  width: 100%;
}

.match-vs-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0 6px;
  flex-shrink: 0;
}
.vs-badge {
  font-size: 11px;
  font-weight: 800;
  color: var(--primary);
  background: rgba(229, 9, 20, 0.12);
  border-radius: 6px;
  padding: 2px 6px;
  margin-bottom: 4px;
}
.match-timer {
  font-size: 11px;
  font-weight: 700;
  color: var(--gold);
}
.match-timer.is-live {
  color: #ef4444;
}

.match-card-bottom {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 11px;
  color: var(--text-muted);
}
.match-btn-watch {
  color: var(--primary);
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 4px;
}

/* ===== CHANNELS GRID ===== */
.channels-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: 12px;
  margin-bottom: 26px;
}
.channel-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px 10px;
  text-align: center;
  cursor: pointer;
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  display: flex;
  flex-direction: column;
  align-items: center;
}
.channel-card:hover {
  transform: translateY(-3px);
  border-color: var(--primary);
  box-shadow: 0 8px 22px rgba(0,0,0,0.3);
}
.channel-logo-wrap {
  width: 58px;
  height: 58px;
  border-radius: 50%;
  background: var(--bg-secondary);
  border: 2px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 8px;
  padding: 4px;
  overflow: hidden;
  transition: transform 0.2s;
}
.channel-card:hover .channel-logo-wrap {
  transform: scale(1.08);
  border-color: var(--primary);
}
.channel-logo-wrap img {
  width: 100%;
  height: 100%;
  border-radius: 50%;
}
.channel-name {
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  width: 100%;
}
.channel-status {
  font-size: 10px;
  color: var(--green);
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 3px;
  font-weight: 600;
}

/* ===== MOVIES / SHOWS / DRAMA GRID ===== */
.movies-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(135px, 1fr));
  gap: 14px;
  margin-bottom: 26px;
}
.movie-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  cursor: pointer;
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
.movie-card:hover {
  transform: translateY(-4px);
  border-color: var(--primary);
  box-shadow: 0 10px 28px rgba(0,0,0,0.35);
}
.movie-poster-wrap {
  position: relative;
  aspect-ratio: 2 / 3;
  width: 100%;
  background: var(--bg-secondary);
  overflow: hidden;
}
.movie-poster-wrap img {
  width: 100%;
  height: 100%;
  transition: transform 0.3s;
}
.movie-card:hover .movie-poster-wrap img {
  transform: scale(1.06);
}
.movie-hd-tag {
  position: absolute;
  top: 6px;
  right: 6px;
  background: rgba(0,0,0,0.75);
  backdrop-filter: blur(4px);
  color: var(--gold);
  font-size: 9px;
  font-weight: 800;
  padding: 2px 6px;
  border-radius: 4px;
  border: 1px solid rgba(245, 158, 11, 0.4);
}
.movie-type-tag {
  position: absolute;
  top: 6px;
  left: 6px;
  background: rgba(229, 9, 20, 0.85);
  color: #fff;
  font-size: 8px;
  font-weight: 800;
  padding: 1px 5px;
  border-radius: 4px;
  text-transform: uppercase;
}
.movie-info {
  padding: 8px 10px 10px;
}
.movie-title {
  font-size: 12px;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.movie-cat {
  font-size: 10px;
  color: var(--text-muted);
  margin-top: 2px;
}

/* ===== VIDEO PLAYER PAGE ===== */
.player-page {
  display: none;
  padding-top: 14px;
}
.player-page.active {
  display: block;
}

.player-back-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}
.back-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: 10px;
  background: var(--card);
  border: 1px solid var(--border);
  color: var(--text);
  font-size: 12px;
  font-weight: 600;
  transition: all 0.2s;
}
.back-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.player-main-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 18px;
  overflow: hidden;
  box-shadow: 0 14px 40px rgba(0,0,0,0.45);
}
.player-video-box {
  width: 100%;
  aspect-ratio: 16 / 9;
  background: #000;
  position: relative;
}
.player-video-box iframe,
.player-video-box video {
  width: 100%;
  height: 100%;
  border: none;
  display: block;
}

.player-details {
  padding: 14px 18px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
}
.player-title {
  font-size: 16px;
  font-weight: 800;
}
.player-meta {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: 2px;
}

.player-servers-wrap {
  padding: 10px 18px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.server-label {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
}
.server-btn {
  padding: 5px 12px;
  border-radius: 8px;
  background: var(--card);
  border: 1px solid var(--border);
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  transition: all 0.2s;
}
.server-btn:hover {
  color: var(--text);
  border-color: var(--primary);
}
.server-btn.active {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

/* Tabbed Player Recommendations */
.player-rec-tabs {
  display: flex;
  align-items: center;
  gap: 8px;
  border-bottom: 1px solid var(--border);
  padding: 16px 0 10px;
  margin-bottom: 16px;
  overflow-x: auto;
}
.p-tab-btn {
  font-size: 12px;
  font-weight: 700;
  padding: 6px 12px;
  border-radius: 8px;
  color: var(--text-muted);
  background: var(--card);
  border: 1px solid var(--border);
  white-space: nowrap;
}
.p-tab-btn.active {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

/* ===== BANNER ADS ===== */
.ad-banner-slot {
  margin: 14px 0;
  border-radius: 12px;
  background: var(--card);
  border: 1px dashed var(--border);
  padding: 8px;
  text-align: center;
  min-height: 50px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.ad-banner-slot.hidden {
  display: none;
}
.ad-tag-label {
  font-size: 8px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 4px;
}

/* Sticky Bottom Ad */
.sticky-ad {
  position: fixed;
  bottom: var(--nav-height);
  left: 0;
  right: 0;
  z-index: 95;
  background: rgba(7, 9, 14, 0.95);
  border-top: 1px solid var(--primary);
  padding: 4px 8px;
  display: none;
  text-align: center;
}
.sticky-ad.show {
  display: block;
}
.sticky-ad-close {
  position: absolute;
  top: -24px;
  right: 12px;
  background: var(--primary);
  color: #fff;
  font-size: 10px;
  padding: 3px 10px;
  border-radius: 6px 6px 0 0;
  font-weight: 700;
}

/* ===== BOTTOM NAVIGATION ===== */
.bottom-nav {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  height: var(--nav-height);
  background: rgba(7, 9, 14, 0.95);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border-top: 1px solid var(--border);
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: space-around;
  padding: 0 4px env(safe-area-inset-bottom);
}
[data-theme='light'] .bottom-nav {
  background: rgba(255, 255, 255, 0.95);
}
.b-nav-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  flex: 1;
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 600;
  padding: 6px 0;
  position: relative;
  transition: all 0.2s;
}
.b-nav-item i {
  font-size: 18px;
  transition: transform 0.2s;
}
.b-nav-item:hover, .b-nav-item.active {
  color: var(--primary);
}
.b-nav-item.active i {
  transform: translateY(-2px);
}
.b-nav-badge {
  position: absolute;
  top: 2px;
  right: calc(50% - 18px);
  background: var(--primary);
  color: #fff;
  font-size: 8px;
  font-weight: 800;
  padding: 1px 5px;
  border-radius: 10px;
  min-width: 16px;
  text-align: center;
}

/* ===== FOOTER ===== */
.site-footer {
  margin-top: 36px;
  border-top: 1px solid var(--border);
  padding: 26px 0 32px;
  text-align: center;
  color: var(--text-muted);
  font-size: 12px;
}
.footer-social-links {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  margin-bottom: 12px;
}
.social-circle-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--card);
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  transition: all 0.2s;
}
.social-circle-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
  transform: translateY(-2px);
}
.footer-copy {
  margin-top: 6px;
}
.footer-dev {
  margin-top: 4px;
  font-size: 11px;
}
.footer-dev strong {
  color: var(--gold);
}

/* ===== MODALS ===== */
.app-modal {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 300;
  background: rgba(0,0,0,0.78);
  backdrop-filter: blur(5px);
  align-items: center;
  justify-content: center;
  padding: 16px;
}
.app-modal.active {
  display: flex;
}
.modal-box {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 18px;
  max-width: 460px;
  width: 100%;
  overflow: hidden;
  box-shadow: 0 16px 40px rgba(0,0,0,0.6);
}
.modal-header {
  padding: 14px 18px;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.modal-body {
  padding: 18px;
  font-size: 13px;
  line-height: 1.6;
}

.state-box {
  text-align: center;
  padding: 40px 16px;
  color: var(--text-muted);
  grid-column: 1 / -1;
}
.state-box i {
  font-size: 32px;
  margin-bottom: 8px;
  color: var(--primary);
}

/* Mobile responsive adjustments */
@media (max-width: 640px) {
  .topbar-center {
    display: none;
  }
  .topbar-center.mobile-active {
    display: flex;
    position: absolute;
    top: var(--header-height);
    left: 0;
    right: 0;
    margin: 0;
    max-width: 100%;
    background: var(--bg-secondary);
    padding: 8px 14px;
    border-bottom: 1px solid var(--border);
    z-index: 99;
  }
  .matches-grid {
    grid-template-columns: 1fr;
  }
  .channels-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 8px;
  }
  .movies-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 8px;
  }
  .hero-slide {
    padding: 16px;
    min-height: 200px;
  }
  .hero-slide-content h2 {
    font-size: 17px;
  }
  .team-logo {
    width: 38px;
    height: 38px;
  }
  .brand-logo {
    font-size: 17px;
  }
}

