body.script:
//
  var WB = (function() {
    'use strict';

    var CFG = window.WB_SITE || {};
    var database = null;

    // State
    var state = {
      matches: {},
      channels: {},
      movies: {},
      settings: {},
      ads: {},
      social: {},
      slides: [],
      currentServers: [],
      currentServerIndex: 0,
      activeFilter: 'all',
      activeSubMovieFilter: 'all',
      activeRecTab: 'matches',
      isPlayerActive: false,
      isDark: true
    };

    // Default Seed Data with Bangladeshi Matches & Real channels
    var DEFAULT_MATCHES = {
      m1: {
        title: 'ICC Champions Trophy 2026',
        team1Name: 'বাংলাদেশ (Bangladesh)',
        team1Logo: 'https://images.unsplash.com/photo-1540747913346-19e32dc3e97e?w=120&auto=format&fit=crop&q=80',
