        status: 'live',
        hot: true,
        servers: [
          { name: 'Server 1 (T Sports HD)', url: 'https://tvsen5.aynaott.com/TnMn5kZz8aLm/index.m3u8' },
          { name: 'Server 2 (Fast 720p)', url: 'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8' }
        ]
      },
      m2: {
        title: 'UEFA Champions League · Quarter Final',
        team1Name: 'রিয়াল মাদ্রিদ (Real Madrid)',
        team1Logo: 'https://images.unsplash.com/photo-1522778119026-d647f0596c20?w=120&auto=format&fit=crop&q=80',
        team2Name: 'ম্যান সিটি (Man City)',
        team2Logo: 'https://images.unsplash.com/photo-1508098682722-e99c43a406b2?w=120&auto=format&fit=crop&q=80',
        startTime: new Date(Date.now() + 120 * 60000).toISOString(),
        endTime: new Date(Date.now() + 240 * 60000).toISOString(),
        status: 'upcoming',
        hot: true,
        servers: [
          { name: 'Server 1 (Sony Ten 1 HD)', url: 'https://bldcmprod-cdn.toffeelive.com/cdn/live/sony_sports_1_hd/playlist.m3u8' },
          { name: 'Server 2 (Ultra Low Buffer)', url: 'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8' }
        ]
      },
      m3: {
        title: 'English Premier League',
        team1Name: 'আর্সেনাল (Arsenal)',
        team1Logo: 'https://images.unsplash.com/photo-1518091043644-c1d4457512c6?w=120&auto=format&fit=crop&q=80',
        team2Name: 'লিভারপুল (Liverpool)',
        team2Logo: 'https://images.unsplash.com/photo-1579952363873-27f3bade9f55?w=120&auto=format&fit=crop&q=80',
        startTime: new Date(Date.now() + 360 * 60000).toISOString(),
        endTime: new Date(Date.now() + 480 * 60000).toISOString(),
        status: 'upcoming',
        servers: [
          { name: 'Star Sports 1 HD', url: 'https://streamhub.dhruvpatil681.workers.dev/1088.m3u8' }
        ]
      }
    };

    var DEFAULT_CHANNELS = {
      c1: { name: 'T Sports HD', category: 'Sports', logoUrl: 'https://i.postimg.cc/Qx3GZn6T/20240823_024117.png', streamUrl: 'https://tvsen5.aynaott.com/TnMn5kZz8aLm/index.m3u8' },
      c2: { name: 'Star Sports 1', category: 'Sports', logoUrl: 'https://i.postimg.cc/DzDHjCJm/20240823_024249.png', streamUrl: 'https://streamhub.dhruvpatil681.workers.dev/1088.m3u8' },
      c3: { name: 'Sony Ten 1', category: 'Sports', logoUrl: 'https://i.postimg.cc/65fsWLS1/20240823_024136.png', streamUrl: 'https://bldcmprod-cdn.toffeelive.com/cdn/live/sony_sports_1_hd/playlist.m3u8' },
      c4: { name: 'Willow Sports', category: 'Cricket', logoUrl: 'https://i.postimg.cc/HntSg3xw/20240823_024624.png', streamUrl: 'https://streamhub.dhruvpatil681.workers.dev/2028.m3u8' },
      c5: { name: 'A Sports HD', category: 'Sports', logoUrl: 'https://i.postimg.cc/W1z5BGPZ/20240823_024712.png', streamUrl: 'https://tvsen6.aynaott.com/zv68oqPDu7MZZwmHhRxt/tracks-v1a1/mono.ts.m3u8' },
      c6: { name: 'PTV Sports', category: 'Sports', logoUrl: 'https://i.postimg.cc/rFKBNjwP/Ptvsportslogo2023.webp', streamUrl: 'https://sm-monirul.top/@monirul_Islam_SM/proxy.php?id=ptv_sports&format=.m3u8' },
      c7: { name: 'Discovery HD', category: 'Docu', logoUrl: 'https://i.postimg.cc/cJ90sMKN/20240823_023541.png', streamUrl: 'http://202.70.146.135:8000/play/a05z/index.m3u8' },
      c8: { name: '9XM Music', category: 'Music', logoUrl: 'https://i.postimg.cc/SRKS6TwR/20240823_022008.png', streamUrl: 'http://103.175.73.12:8080/live/155/155_0.m3u8' }
    };

    var DEFAULT_MOVIES = {
      m1: { title: 'তুফান (Toofan)', category: 'bangla_movie', type: 'সিনেমা', thumbnailUrl: 'https://images.unsplash.com/photo-1536440136628-849c177e76a1?w=300&auto=format&fit=crop&q=80', videoUrl: 'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8' },
      m2: { title: 'প্রিয়তমা (Priyotoma)', category: 'bangla_movie', type: 'সিনেমা', thumbnailUrl: 'https://images.unsplash.com/photo-1485846234645-a62644f84728?w=300&auto=format&fit=crop&q=80', videoUrl: 'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8' },
      m3: { title: 'ব্যাচেলর পয়েন্ট (Bachelor Point)', category: 'natok', type: 'নাটক', thumbnailUrl: 'https://images.unsplash.com/photo-1517604931442-7e0c8ed2963c?w=300&auto=format&fit=crop&q=80', videoUrl: 'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8' },
      m4: { title: 'কারাগার (Karagar Series)', category: 'series', type: 'সিরিজ', thumbnailUrl: 'https://images.unsplash.com/photo-1509281373149-e957c6296406?w=300&auto=format&fit=crop&q=80', videoUrl: 'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8' },
      m5: { title: 'সাল্যার (Salaar Part 1)', category: 'hindi', type: 'হিন্দি', thumbnailUrl: 'https://images.unsplash.com/photo-1534447677768-be436bb09401?w=300&auto=format&fit=crop&q=80', videoUrl: 'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8' },
      m6: { title: 'Dune: Part Two', category: 'action', type: 'হলিউড', thumbnailUrl: 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=300&auto=format&fit=crop&q=80', videoUrl: 'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8' }
    };

    function esc(s) {
      return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }

    function initFirebase() {
      try {
        if (window.firebase && CFG.FIREBASE_CONFIG) {
          window.firebase.initializeApp(CFG.FIREBASE_CONFIG);
          database = window.firebase.database();
          syncData();
          initVisitors();
        } else {
          loadDefaults();
        }
      } catch (err) {
        console.warn('Firebase fallback to REST:', err);
        fetchFromRest();
      }
    }

    function fetchFromRest() {
      // Direct REST calls to user's Firebase RTDB
      fetch('https://webcastbd-4070e-default-rtdb.firebaseio.com/liveChannels.json')
        .then(function(r) { return r.json(); })
        .then(function(ch) {
          if (ch && Object.keys(ch).length) {
            state.channels = ch;
            renderChannels();
          }
        }).catch(function() {});

      fetch('https://webcastbd-4070e-default-rtdb.firebaseio.com/movies.json')
        .then(function(r) { return r.json(); })
        .then(function(mv) {
          if (mv && Object.keys(mv).length) {
            // Merge with default natok/series so all categories work
            state.movies = Object.assign({}, DEFAULT_MOVIES, mv);
            renderMovies();
          }
        }).catch(function() {});

      fetch('https://webcastbd-4070e-default-rtdb.firebaseio.com/settings.json')
        .then(function(r) { return r.json(); })
        .then(function(st) {
          if (st) {
            state.settings = st;
            if (st.noticeText) {
              document.getElementById('ticker-marquee').innerHTML = '<span><i class="fas fa-bullhorn"></i> ' + esc(st.noticeText) + '</span>';
            }
            if (st.onlineUsers) {
              updateOnlineDisplay(st.onlineUsers);
            }
          }
        }).catch(function() {});

      fetch('https://webcastbd-4070e-default-rtdb.firebaseio.com/ads.json')
        .then(function(r) { return r.json(); })
        .then(function(ads) {
          if (ads) {
            state.ads = ads;
            renderAds();
          }
        }).catch(function() {});
    }

    function loadDefaults() {
      state.matches = DEFAULT_MATCHES;
      state.channels = DEFAULT_CHANNELS;
      state.movies = DEFAULT_MOVIES;
      renderAll();
    }

    function syncData() {
      if (!database) return;
      var paths = CFG.DB_PATHS;

      database.ref(paths.matches).on('value', function(snap) {
        var val = snap.val();
        state.matches = (val && Object.keys(val).length > 0) ? val : DEFAULT_MATCHES;
        renderMatches();
        updateMatchBadge();
      });

      database.ref(paths.channels).on('value', function(snap) {
        var val = snap.val();
        state.channels = (val && Object.keys(val).length > 0) ? val : DEFAULT_CHANNELS;
        renderChannels();
      });

      database.ref(paths.movies).on('value', function(snap) {
        var val = snap.val();
        state.movies = (val && Object.keys(val).length > 0) ? Object.assign({}, DEFAULT_MOVIES, val) : DEFAULT_MOVIES;
        renderMovies();
      });

      database.ref(paths.settings).on('value', function(snap) {
        var val = snap.val();
        if (val) {
          state.settings = val;
          if (val.noticeText) {
            document.getElementById('ticker-marquee').innerHTML = '<span><i class="fas fa-bullhorn"></i> ' + esc(val.noticeText) + '</span>';
          }
          if (val.telegramLink) {
            var el = document.getElementById('drawer-telegram-link');
            if (el) el.href = val.telegramLink;
          }
          if (val.alert && val.alert.message) {
            showNoticeModal(val.alert.title || 'বিজ্ঞপ্তি', val.alert.message);
          }
        }
      });
    }

    function initVisitors() {
      if (!database) return;
      var visitorId = 'v_' + Math.random().toString(36).substr(2, 9);
      var visRef = database.ref(CFG.DB_PATHS.visitors + '/' + visitorId);

      visRef.set({
        online: true,
        lastSeen: window.firebase.database.ServerValue.TIMESTAMP
      });
      visRef.onDisconnect().remove();

      database.ref(CFG.DB_PATHS.visitors).on('value', function(snap) {
        var count = snap.numChildren();
        var displayCount = count > 0 ? (1200 + count) : 1320;
        updateOnlineDisplay(displayCount);
      });
    }

    function updateOnlineDisplay(count) {
      var el1 = document.getElementById('online-counter');
      var el2 = document.getElementById('drawer-online-count');
      if (el1) el1.textContent = count.toLocaleString('bn-BD');
      if (el2) el2.textContent = count.toLocaleString('bn-BD');
    }

    function formatTimeRemaining(targetMs) {
      var diff = targetMs - Date.now();
      if (diff <= 0) return 'শুরু হচ্ছে...';
      var d = Math.floor(diff / 86400000);
      var h = Math.floor((diff % 86400000) / 3600000);
      var m = Math.floor((diff % 3600000) / 60000);
      var s = Math.floor((diff % 60000) / 1000);

      if (d > 0) return d + 'd ' + h + 'h ' + m + 'm';
      return (h < 10 ? '0' + h : h) + ':' + (m < 10 ? '0' + m : m) + ':' + (s < 10 ? '0' + s : s);
    }

    function getMatchRank(m) {
      var now = Date.now();
      var s = m.startTime ? new Date(m.startTime).getTime() : NaN;
      if (isNaN(s)) return 2;
      var e = m.endTime ? new Date(m.endTime).getTime() : s + 3 * 3600000;
      if (now >= s && now <= e) return 1; // Live
      if (now < s) return 2; // Upcoming
      return 3; // Finished
    }

    function renderMatches() {
      var container = document.getElementById('matches-grid');
      if (!container) return;

      var keys = Object.keys(state.matches);
      if (!keys.length) {
        container.innerHTML = '<div class="state-box"><i class="fas fa-futbol"></i><p>বর্তমানে কোনো লাইভ ম্যাচ নেই</p></div>';
        return;
      }

      var html = keys.map(function(k) {
        var m = state.matches[k];
        var rank = getMatchRank(m);
        var statusLabel = rank === 1 ? '🔴 লাইভ (LIVE)' : rank === 2 ? 'আসন্ন (Upcoming)' : 'সমাপ্ত';
        var statusClass = rank === 1 ? 'live' : 'upcoming';
        var timeDisplay = rank === 1 ? 'LIVE' : formatTimeRemaining(new Date(m.startTime).getTime());

        return '<div class="match-card" onclick="WB.openMatch(\'' + esc(k) + '\')">' +
          '<div class="match-top">' +
            '<span class="match-tournament"><i class="fas fa-trophy" style="color:var(--gold);margin-right:4px"></i>' + esc(m.title || 'Tournament') + '</span>' +
            '<span class="match-status-badge ' + statusClass + '">' + statusLabel + '</span>' +
          '</div>' +
          '<div class="match-teams-row">' +
            '<div class="team-item">' +
              '<img class="team-logo" src="' + esc(m.team1Logo || CFG.FALLBACK_LOGO) + '" alt="' + esc(m.team1Name) + '" onerror="this.src=\'' + CFG.FALLBACK_LOGO + '\'"/>' +
              '<span class="team-name">' + esc(m.team1Name || 'Team 1') + '</span>' +
            '</div>' +
            '<div class="match-vs-box">' +
              '<span class="vs-badge">VS</span>' +
              '<span class="match-timer ' + (rank === 1 ? 'is-live' : '') + '">' + timeDisplay + '</span>' +
            '</div>' +
            '<div class="team-item">' +
              '<img class="team-logo" src="' + esc(m.team2Logo || CFG.FALLBACK_LOGO) + '" alt="' + esc(m.team2Name) + '" onerror="this.src=\'' + CFG.FALLBACK_LOGO + '\'"/>' +
              '<span class="team-name">' + esc(m.team2Name || 'Team 2') + '</span>' +
            '</div>' +
          '</div>' +
          '<div class="match-card-bottom">' +
            '<span><i class="far fa-clock"></i> সরাসরি সম্প্রচার</span>' +
            '<span class="match-btn-watch"><i class="fas fa-play-circle"></i> দেখুন</span>' +
          '</div>' +
        '</div>';
      }).join('');

      container.innerHTML = html;
    }

    function renderChannels() {
      var container = document.getElementById('channels-grid');
      if (!container) return;

      var keys = Object.keys(state.channels);
      if (!keys.length) {
        container.innerHTML = '<div class="state-box"><p>কোনো চ্যানেল পাওয়া যায়নি</p></div>';
        return;
      }

      var html = keys.map(function(k) {
        var c = state.channels[k];
        return '<div class="channel-card" onclick="WB.openChannel(\'' + esc(k) + '\')">' +
          '<div class="channel-logo-wrap">' +
            '<img src="' + esc(c.logoUrl || CFG.FALLBACK_LOGO) + '" alt="' + esc(c.name) + '" onerror="this.src=\'' + CFG.FALLBACK_LOGO + '\'"/>' +
          '</div>' +
          '<span class="channel-name">' + esc(c.name || 'Channel') + '</span>' +
          '<span class="channel-status"><span class="pulse-dot"></span> LIVE</span>' +
        '</div>';
      }).join('');

      container.innerHTML = html;
    }

    function renderMovies() {
      var container = document.getElementById('movies-grid');
      if (!container) return;

      var keys = Object.keys(state.movies);
      var sub = state.activeSubMovieFilter;
      var filteredKeys = keys.filter(function(k) {
        if (sub === 'all') return true;
        var item = state.movies[k];
        return item.category === sub || (item.category && item.category.indexOf(sub) !== -1);
      });

      if (!filteredKeys.length) {
        container.innerHTML = '<div class="state-box"><p>এই ক্যাটাগরিতে কোনো ভিডিও পাওয়া যায়নি</p></div>';
        return;
      }

      var html = filteredKeys.map(function(k) {
        var m = state.movies[k];
        var typeLabel = m.type || (m.category === 'natok' ? 'নাটক' : m.category === 'series' ? 'সিরিজ' : 'সিনেমা');
        return '<div class="movie-card" onclick="WB.openMovie(\'' + esc(k) + '\')">' +
          '<div class="movie-poster-wrap">' +
            '<span class="movie-type-tag">' + esc(typeLabel) + '</span>' +
            '<span class="movie-hd-tag">HD</span>' +
            '<img src="' + esc(m.thumbnailUrl || CFG.FALLBACK_LOGO) + '" alt="' + esc(m.title) + '" onerror="this.src=\'' + CFG.FALLBACK_LOGO + '\'"/>' +
          '</div>' +
          '<div class="movie-info">' +
            '<div class="movie-title">' + esc(m.title || 'Movie') + '</div>' +
            '<div class="movie-cat">' + esc(m.category || 'HD') + '</div>' +
          '</div>' +
        '</div>';
      }).join('');

      container.innerHTML = html;
    }

    function filterSubMovies(subCategory, btn) {
      state.activeSubMovieFilter = subCategory;
      var chips = document.querySelectorAll('#movie-sub-chips .sub-chip');
      chips.forEach(function(c) { c.classList.remove('active'); });
      if (btn) btn.classList.add('active');
      renderMovies();
    }

    function updateMatchBadge() {
      var count = Object.keys(state.matches).length;
      var el = document.getElementById('b-nav-matches-count');
      if (el) el.textContent = count;
    }

    function renderAll() {
      renderMatches();
      renderChannels();
      renderMovies();
      updateMatchBadge();
    }

    // Player Logic
    function openPlayer(title, desc, servers) {
      state.currentServers = servers || [];
      state.currentServerIndex = 0;
      state.isPlayerActive = true;

      document.getElementById('home-view').style.display = 'none';
      var pView = document.getElementById('player-view');
      pView.classList.add('active');

      document.getElementById('player-current-title').textContent = title;
      document.getElementById('player-current-desc').textContent = desc || 'HD Streaming Player';

      renderServerButtons();
      loadActiveServer();
      renderPlayerRecommendations();
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function renderServerButtons() {
      var wrap = document.getElementById('player-server-buttons');
      if (!wrap) return;

      if (!state.currentServers.length) {
        wrap.innerHTML = '<span style="font-size:11px;color:var(--text-muted)">Default Server</span>';
        return;
      }

      wrap.innerHTML = state.currentServers.map(function(s, idx) {
        var active = idx === state.currentServerIndex ? 'active' : '';
        return '<button class="server-btn ' + active + '" onclick="WB.switchServer(' + idx + ')"><i class="fas fa-play" style="font-size:9px;margin-right:4px"></i>' + esc(s.name || 'Server ' + (idx + 1)) + '</button>';
      }).join('');
    }

    function loadActiveServer() {
      var box = document.getElementById('player-box');
      if (!box) return;

      var server = state.currentServers[state.currentServerIndex];
      if (!server || !server.url) {
        box.innerHTML = '<div class="state-box"><i class="fas fa-exclamation-triangle"></i><p>ভিডিও লিংক পাওয়া যায়নি</p></div>';
        return;
      }

      var url = server.url;
      document.getElementById('player-active-server-name').textContent = server.name || 'Server ' + (state.currentServerIndex + 1);

      if (url.indexOf('.m3u8') !== -1) {
        box.innerHTML = '<video id="active-video-tag" controls autoplay playsinline style="width:100%;height:100%;background:#000"></video>';
        var video = document.getElementById('active-video-tag');
        if (window.Hls && window.Hls.isSupported()) {
          var hls = new window.Hls();
          hls.loadSource(url);
          hls.attachMedia(video);
        } else if (video.canPlayType('application/vnd.apple.mpegurl')) {
          video.src = url;
        }
      } else {
        box.innerHTML = '<iframe src="' + esc(url) + '" allowfullscreen allow="autoplay; encrypted-media"></iframe>';
      }
    }

    function switchServer(idx) {
      state.currentServerIndex = idx;
      renderServerButtons();
      loadActiveServer();
    }

    function closePlayer() {
      state.isPlayerActive = false;
      var box = document.getElementById('player-box');
      if (box) box.innerHTML = '';
      document.getElementById('player-view').classList.remove('active');
      document.getElementById('home-view').style.display = 'block';
    }

    function switchPlayerRecTab(tabType, btn) {
      state.activeRecTab = tabType;
      var btns = document.querySelectorAll('.player-rec-tabs .p-tab-btn');
      btns.forEach(function(b) { b.classList.remove('active'); });
      if (btn) btn.classList.add('active');
      renderPlayerRecommendations();
    }

    function renderPlayerRecommendations() {
      var grid = document.getElementById('player-rec-grid');
      if (!grid) return;

      var tab = state.activeRecTab;

      if (tab === 'matches') {
        var mKeys = Object.keys(state.matches).slice(0, 4);
        grid.innerHTML = mKeys.map(function(k) {
          var m = state.matches[k];
          return '<div class="match-card" onclick="WB.openMatch(\'' + esc(k) + '\')">' +
            '<div class="match-top"><span class="match-tournament">' + esc(m.title) + '</span><span class="match-status-badge live">LIVE</span></div>' +
            '<div class="match-teams-row">' +
              '<span class="team-name" style="font-weight:700">' + esc(m.team1Name) + ' vs ' + esc(m.team2Name) + '</span>' +
              '<span class="match-btn-watch"><i class="fas fa-play"></i></span>' +
            '</div>' +
          '</div>';
        }).join('');
      } else if (tab === 'channels') {
        var cKeys = Object.keys(state.channels).slice(0, 6);
        grid.innerHTML = cKeys.map(function(k) {
          var c = state.channels[k];
          return '<div class="match-card" onclick="WB.openChannel(\'' + esc(k) + '\')">' +
            '<div style="display:flex;align-items:center;gap:10px">' +
              '<img src="' + esc(c.logoUrl || CFG.FALLBACK_LOGO)" style="width:34px;height:34px;border-radius:50%;object-fit:cover"/>' +
              '<span style="font-weight:700;font-size:12px;flex:1">' + esc(c.name) + '</span>' +
              '<span class="match-btn-watch"><i class="fas fa-play"></i></span>' +
            '</div>' +
          '</div>';
        }).join('');
      } else if (tab === 'movies') {
        var movKeys = Object.keys(state.movies).slice(0, 4);
        grid.innerHTML = movKeys.map(function(k) {
          var mv = state.movies[k];
          return '<div class="match-card" onclick="WB.openMovie(\'' + esc(k) + '\')">' +
            '<div style="display:flex;align-items:center;gap:10px">' +
              '<img src="' + esc(mv.thumbnailUrl || CFG.FALLBACK_LOGO)" style="width:34px;height:48px;border-radius:6px;object-fit:cover"/>' +
              '<div style="flex:1"><span style="font-weight:700;font-size:12px;display:block">' + esc(mv.title) + '</span><span style="font-size:10px;color:var(--text-muted)">' + esc(mv.category) + '</span></div>' +
              '<span class="match-btn-watch"><i class="fas fa-play"></i></span>' +
            '</div>' +
          '</div>';
        }).join('');
      }
    }

    function openMatch(key) {
      var m = state.matches[key];
      if (!m) return;
      var servers = m.servers && m.servers.length ? m.servers : [{ name: 'Server 1 HD', url: m.streamUrl || 'https://tvsen5.aynaott.com/TnMn5kZz8aLm/index.m3u8' }];
      openPlayer(m.title + ' (' + m.team1Name + ' vs ' + m.team2Name + ')', 'লাইভ স্পোর্টস সম্প্রচার', servers);
    }

    function openChannel(key) {
      var c = state.channels[key];
      if (!c) return;
      var servers = [{ name: c.name + ' HD', url: c.streamUrl || 'https://tvsen5.aynaott.com/TnMn5kZz8aLm/index.m3u8' }];
      openPlayer(c.name, 'লাইভ টিভি স্ট্রিমিং', servers);
    }

    function openMovie(key) {
      var m = state.movies[key];
      if (!m) return;
      var servers = [{ name: 'HD Streaming Server', url: m.videoUrl || 'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8' }];
      openPlayer(m.title, m.category || 'HD Movie', servers);
    }

    function playFeatured() {
      var keys = Object.keys(state.matches);
      if (keys.length) openMatch(keys[0]);
    }

    function setFilter(filter, sub) {
      state.activeFilter = filter;
      if (sub) state.activeSubMovieFilter = sub;

      var tabs = document.querySelectorAll('.filter-tabs .tab-btn');
      tabs.forEach(function(t) {
        t.classList.toggle('active', t.getAttribute('data-filter') === filter);
      });

      var bNavs = document.querySelectorAll('.b-nav-item');
      bNavs.forEach(function(n) {
        n.classList.toggle('active', n.getAttribute('data-target') === filter);
      });

      var secMatches = document.getElementById('sec-matches');
      var secChannels = document.getElementById('sec-channels');
      var secMovies = document.getElementById('sec-movies');
      var hero = document.getElementById('hero-slider-wrap');

      if (state.isPlayerActive) closePlayer();

      if (filter === 'all') {
        if (secMatches) secMatches.style.display = 'block';
        if (secChannels) secChannels.style.display = 'block';
        if (secMovies) secMovies.style.display = 'block';
        if (hero) hero.style.display = 'block';
      } else if (filter === 'matches') {
        if (secMatches) secMatches.style.display = 'block';
        if (secChannels) secChannels.style.display = 'none';
        if (secMovies) secMovies.style.display = 'none';
        if (hero) hero.style.display = 'block';
      } else if (filter === 'channels') {
        if (secMatches) secMatches.style.display = 'none';
        if (secChannels) secChannels.style.display = 'block';
        if (secMovies) secMovies.style.display = 'none';
        if (hero) hero.style.display = 'none';
      } else if (filter === 'movies') {
        if (secMatches) secMatches.style.display = 'none';
        if (secChannels) secChannels.style.display = 'none';
        if (secMovies) secMovies.style.display = 'block';
        if (hero) hero.style.display = 'none';
        renderMovies();
      }

      if (document.getElementById('drawer').classList.contains('active')) {
        toggleDrawer();
      }
    }

    function goHome() {
      if (state.isPlayerActive) closePlayer();
      setFilter('all');
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function toggleDrawer() {
      var d = document.getElementById('drawer');
      var o = document.getElementById('drawer-overlay');
      d.classList.toggle('active');
      o.classList.toggle('active');
    }

    function toggleTheme() {
      state.isDark = !state.isDark;
      document.documentElement.setAttribute('data-theme', state.isDark ? 'dark' : 'light');
      var icon1 = document.getElementById('topbar-theme-icon');
      var icon2 = document.getElementById('drawer-theme-icon');
      var iconClass = state.isDark ? 'fas fa-moon' : 'fas fa-sun';
      if (icon1) icon1.className = iconClass;
      if (icon2) icon2.className = iconClass;
    }

    function toggleSearchMobile() {
      var s = document.getElementById('topbar-search-box');
      s.classList.toggle('mobile-active');
      if (s.classList.contains('mobile-active')) {
        document.getElementById('search-input').focus();
      }
    }

    function handleSearch(q) {
      q = (q || '').toLowerCase().trim();
      var mCards = document.querySelectorAll('.match-card');
      mCards.forEach(function(c) {
        c.style.display = (!q || c.textContent.toLowerCase().indexOf(q) !== -1) ? '' : 'none';
      });

      var cCards = document.querySelectorAll('.channel-card');
      cCards.forEach(function(c) {
        c.style.display = (!q || c.textContent.toLowerCase().indexOf(q) !== -1) ? '' : 'none';
      });

      var movieCards = document.querySelectorAll('.movie-card');
      movieCards.forEach(function(c) {
        c.style.display = (!q || c.textContent.toLowerCase().indexOf(q) !== -1) ? '' : 'none';
      });
    }

    function toggleFullscreen() {
      var box = document.getElementById('player-box');
      if (!box) return;
      if (!document.fullscreenElement) {
        box.requestFullscreen().catch(function() {});
      } else {
        document.exitFullscreen().catch(function() {});
      }
    }

    function reloadPlayer() {
      loadActiveServer();
    }

    function showNoticeModal(title, msg) {
      document.getElementById('modal-notice-title').textContent = title;
      document.getElementById('modal-notice-body').textContent = msg;
      document.getElementById('notice-modal').classList.add('active');
    }

    function closeNoticeModal() {
      document.getElementById('notice-modal').classList.remove('active');
    }

    function closeStickyAd() {
      document.getElementById('sticky-ad').classList.remove('show');
    }

    function renderAds() {
      if (!state.ads) return;
      if (state.ads.top && state.ads.top.enabled && state.ads.top.code) {
        var topAd = document.getElementById('ad-top-content');
        var slot = document.getElementById('ad-top-slot');
        if (topAd && slot) {
          topAd.innerHTML = state.ads.top.code;
          slot.classList.remove('hidden');
        }
      }
      if (state.ads.sticky && state.ads.sticky.enabled && state.ads.sticky.code) {
        var stickyAd = document.getElementById('sticky-ad');
        var stickyContent = document.getElementById('sticky-ad-content');
        if (stickyAd && stickyContent) {
          stickyContent.innerHTML = state.ads.sticky.code;
          stickyAd.classList.add('show');
        }
      }
    }

    // Auto-update countdowns every second
    setInterval(function() {
      var timers = document.querySelectorAll('.match-card .match-timer:not(.is-live)');
      if (timers.length) {
        renderMatches();
      }
    }, 1000);

    // Initializer
    function init() {
      loadDefaults();
      initFirebase();
      fetchFromRest();
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', init);
    } else {
      init();
    }

    return {
      openMatch: openMatch,
      openChannel: openChannel,
      openMovie: openMovie,
      closePlayer: closePlayer,
      switchServer: switchServer,
      setFilter: setFilter,
      filterSubMovies: filterSubMovies,
      switchPlayerRecTab: switchPlayerRecTab,
      goHome: goHome,
      toggleDrawer: toggleDrawer,
      toggleTheme: toggleTheme,
      toggleSearchMobile: toggleSearchMobile,
      handleSearch: handleSearch,
      toggleFullscreen: toggleFullscreen,
      reloadPlayer: reloadPlayer,
      playFeatured: playFeatured,
      closeNoticeModal: closeNoticeModal,
      closeStickyAd: closeStickyAd
    };
  })();
  //
